# =============================================================================
# make_testdata.R
# Purpose : Write synthetic TestData for Aim 2 with known ground truth. The
#           cohort itself is simulated in R/sim_cohort.R (simulate_cohort);
#           this file only writes it to disk with the data-contract README.
# Inputs  : config (paths, data contract, model defaults); scenario.
# Outputs : TestData/ (main) or TestData/stress/ with the files listed in
#           config$data$files, README.md, and truth/ (read only by step V).
#
# Standalone use:  Rscript Code/testdata/make_testdata.R [--scenario stress]
# =============================================================================

# ---- README (data contract) ----------------------------------------------------------------
write_readme <- function(dir, spec) {
  txt <- c(
    "# Aim 2 data contract (TestData = synthetic example of the real Data/ format)",
    "",
    sprintf("Scenario: **%s**. Generated by `Code/testdata/make_testdata.R`. All values are synthetic.", spec$scenario),
    "",
    "Days are counted relative to CAR T infusion (day 0); lymphodepletion runs on days -5 to -3.",
    "No calendar dates are stored. Units: ANC, PLT, WBC, ALC x10^9/L; Hb g/dL; CRP mg/L; ferritin ng/mL.",
    "",
    "| File | One row per | Columns |",
    "|---|---|---|",
    "| `patients.csv` | patient | patient_id, age, sex, product, costim, prior_lines, prior_asct, prior_bendamustine, months_since_last_chemo, bridging, ld_flu_total, ld_cy_total, ld_dose_reduced, crs_grade, crs_onset_day, crs_end_day, marrow_involvement, iec_hs, viral_infection, relapse_day, subsequent_tx_day, death_day, last_followup_day, phenotype_clinical (optional) |",
    "| `labs_long.csv` | blood count | patient_id, day, anc, plt, wbc, hgb, alc, mcv (optional, fL), rdw (optional, %) (ANC below 0.01 reported as 0) |",
    "| `inflam_long.csv` | inflammatory lab | patient_id, day, crp, ferritin |",
    "| `events.csv` | intervention | patient_id, event (gcsf, plt_tx, rbc_tx, tpo_ra, cd34_boost, tocilizumab, steroid, anakinra), start_day, end_day, dose |",
    "| `split.csv` | patient | patient_id, split (train/test), locked_at, seed |",
    "| `mutation_tested.csv` | sequenced patient | patient_id, sample_day, sample_timepoint (apheresis/post_bridging/pre_LD), sample_type (PB/BM), lod_vaf, panel_version |",
    "| `mutations_pre.csv` | variant (pre-treatment) | patient_id, gene, protein_change, vaf, depth. Tested patients without a row are **negative** |",
    "| `post_samples_planned.csv` | planned post-treatment sample | patient_id, sample_day, sample_type, indication |",
    "| `later/mutations_post.csv` | variant (post-treatment) | patient_id, sample_day, gene, protein_change, vaf, depth. Arrives later; read only after pre-registration |",
    "",
    "`truth/` holds the generating parameters. Analysis steps never read it; only validation step V does.")
  writeLines(txt, file.path(dir, "README.md"))
}

# ---- main ------------------------------------------------------------------------------------
make_testdata <- function(config, scenario = "main", seed = NULL) {
  out_dir <- if (scenario == "stress") file.path(config$paths$root, "TestData", "stress")
             else file.path(config$paths$root, "TestData")
  dir.create(file.path(out_dir, "truth"), recursive = TRUE, showWarnings = FALSE)
  dir.create(file.path(out_dir, "later"), recursive = TRUE, showWarnings = FALSE)
  sim <- simulate_cohort(config, scenario, seed)
  raw <- sim$raw

  fw <- function(x, f) data.table::fwrite(x, file.path(out_dir, f))
  fw(raw$patients, "patients.csv")
  fw(raw$labs, "labs_long.csv")
  fw(raw$inflam, "inflam_long.csv")
  fw(raw$events, "events.csv")
  fw(raw$split, "split.csv")
  fw(raw$mut_tested, "mutation_tested.csv")
  fw(raw$mut_pre, "mutations_pre.csv")
  fw(raw$post_planned, "post_samples_planned.csv")
  fw(sim$post_muts, file.path("later", "mutations_post.csv"))
  write_readme(out_dir, sim$spec)

  fw(sim$truth$patient, file.path("truth", "true_params_patient.csv"))
  fw(sim$truth$traj[, .(patient_id, day, anc = round(anc, 4), plt = round(plt, 2), is = round(is, 5),
                        f_clone = round(f_clone, 5))], file.path("truth", "true_trajectories.csv"))
  jsonlite::write_json(sim$truth$model, file.path(out_dir, "truth", "true_model.json"), auto_unbox = TRUE,
                       pretty = TRUE, digits = NA)

  ph_true <- sim$truth$patient
  tab <- table(factor(ph_true$phenotype_true, phenotype_levels), useNA = "ifany")
  message(sprintf("TestData (%s) written to %s", scenario, out_dir))
  message("  true phenotypes: ", paste(names(tab), tab, sep = "=", collapse = "  "))
  message("  persistent mechanisms: ",
          paste(names(table(ph_true[phenotype_true == "persistent", mechanism_true])),
                table(ph_true[phenotype_true == "persistent", mechanism_true]), sep = "=", collapse = "  "))
  invisible(list(dir = out_dir, n = nrow(raw$patients), phenotype_true = tab))
}

# ---- standalone entry ---------------------------------------------------------------------
if (sys.nframe() == 0L) {
  args <- commandArgs(trailingOnly = TRUE)
  scenario <- if ("--scenario" %in% args) args[which(args == "--scenario") + 1] else "main"
  here <- normalizePath(dirname(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE))))
  source(file.path(here, "..", "config.R"))
  suppressPackageStartupMessages(library(data.table))
  for (f in c("model_params.R", "model_inputs.R", "model_simulate.R", "phenotype.R", "sim_clinical.R",
              "sim_cohort.R"))
    source(file.path(here, "..", "R", f))
  cfg <- make_config("test", root = normalizePath(file.path(here, "..", "..")))
  make_testdata(cfg, scenario = scenario)
}
